import React, { useState } from 'react';
import './slider.css';

const SWIPE_THRESHOLD = 50;

export default function Slider(props) {
  const [slideIndex, setSlideIndex] = useState(0);
  const [touchStartX, setTouchStartX] = useState(null);
  const slideCount = props.header?.length ?? 0;

  function goToSlide(index) {
    if (slideCount === 0) return;
    setSlideIndex((index + slideCount) % slideCount);
  }

  function nextSlide() {
    goToSlide(slideIndex + 1);
  }

  function prevSlide() {
    goToSlide(slideIndex - 1);
  }

  function handleTouchStart(event) {
    setTouchStartX(event.targetTouches[0].clientX);
  }

  function handleTouchEnd(event) {
    if (touchStartX === null) return;

    const diff = touchStartX - event.changedTouches[0].clientX;
    if (diff > SWIPE_THRESHOLD) nextSlide();
    else if (diff < -SWIPE_THRESHOLD) prevSlide();

    setTouchStartX(null);
  }

  function handlePointerDown(event) {
    setTouchStartX(event.clientX);
  }

  function handlePointerUp(event) {
    if (touchStartX === null) return;

    const diff = touchStartX - event.clientX;
    if (diff > SWIPE_THRESHOLD) nextSlide();
    else if (diff < -SWIPE_THRESHOLD) prevSlide();

    setTouchStartX(null);
  }

  const hasNext = slideIndex < slideCount - 1;
  const hasPrev = slideIndex > 0;

  return (
    <div
      className={`container-slider${hasNext ? ' has-next' : ''}${hasPrev ? ' has-prev' : ''}`}
    >
      <div
        className="slide-viewport"
        onTouchStart={handleTouchStart}
        onTouchEnd={handleTouchEnd}
        onPointerDown={handlePointerDown}
        onPointerUp={handlePointerUp}
        role="region"
        aria-roledescription="carousel"
        aria-label={props.header ? props.header[slideIndex] : 'Experience details'}
      >
        <p className="slider-hint">Swipe to explore</p>
        <div className="slide-content-wrapper" key={slideIndex}>
          <h3 className="slide-content-header">
            {props.header ? props.header[slideIndex] : 'no header was passed'}
          </h3>
          <div className="slide-content">
            {props.data ? props.data[slideIndex] : 'no data was passed'}
          </div>
        </div>
      </div>

      {slideCount > 1 && (
        <div className="slider-dots" role="tablist" aria-label="Slide navigation">
          {props.header.map((label, index) => (
            <button
              key={label}
              type="button"
              className={`slider-dot${index === slideIndex ? ' active' : ''}`}
              onClick={() => goToSlide(index)}
              aria-label={`Go to ${label}`}
              aria-selected={index === slideIndex}
              role="tab"
            />
          ))}
        </div>
      )}
    </div>
  );
}
